CREATE TABLE "added_rule_sets" ("id" INTEGER NOT NULL, "profile_id" INTEGER NOT NULL REFERENCES profiles (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "url" TEXT NOT NULL, "cache_generation" TEXT NULL, "behavior" TEXT NOT NULL, "format" TEXT NOT NULL, "interval" INTEGER NOT NULL DEFAULT 86400, PRIMARY KEY ("id"), UNIQUE ("profile_id", "name"));
CREATE TABLE "clash_providers" ("id" INTEGER NOT NULL, "kind" TEXT NOT NULL, "label" TEXT NOT NULL, "url" TEXT NOT NULL, "behavior" TEXT NULL, "format" TEXT NULL, "order" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "custom_proxies" ("id" INTEGER NOT NULL, "definition" TEXT NOT NULL, "order" TEXT NULL, "empty_options" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "disabled_rules" ("profile_id" INTEGER NOT NULL REFERENCES profiles (id) ON DELETE CASCADE, "rule_id" INTEGER NOT NULL REFERENCES rules (id) ON DELETE CASCADE, PRIMARY KEY ("profile_id", "rule_id"));
CREATE TABLE "icon_records" ("url" TEXT NOT NULL, "last_accessed" INTEGER NOT NULL, PRIMARY KEY ("url"));
CREATE TABLE "icon_sets" ("id" INTEGER NOT NULL, "name" TEXT NOT NULL, "url" TEXT NOT NULL, "icons" TEXT NOT NULL, "last_update_time" INTEGER NULL, "order" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "ip_qualities" ("ip" TEXT NOT NULL, "quality" TEXT NOT NULL, "checked_at" INTEGER NOT NULL, PRIMARY KEY ("ip"));
CREATE TABLE "mitm_modules" ("id" INTEGER NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "url" TEXT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "order" INTEGER NULL, "arguments" TEXT NOT NULL DEFAULT '{}', "resources" TEXT NOT NULL DEFAULT '{}', "system" TEXT NULL, "scripts" INTEGER NOT NULL DEFAULT 0, "rules_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("rules_enabled" IN (0, 1)), "last_update_time" INTEGER NOT NULL, "pending_time" INTEGER NULL, "error" TEXT NULL, "failure" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "mitm_rewrites" ("id" INTEGER NOT NULL, "profile_id" INTEGER NULL REFERENCES profiles (id) ON DELETE CASCADE, "section" TEXT NOT NULL, "line" TEXT NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "order" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "mitm_scripts" ("id" INTEGER NOT NULL, "profile_id" INTEGER NULL REFERENCES profiles (id) ON DELETE CASCADE, "line" TEXT NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "order" TEXT NULL, "url" TEXT NULL, "source" TEXT NOT NULL DEFAULT '', "file" TEXT NOT NULL, "pending_file" TEXT NULL, "checked_at" INTEGER NULL, "error" TEXT NULL, "failure" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "mount_source_statuses" ("source_id" INTEGER NOT NULL REFERENCES profiles (id) ON DELETE CASCADE, "failure" TEXT NULL, "failed_at" INTEGER NULL, "succeeded_at" INTEGER NULL, PRIMARY KEY ("source_id"));
CREATE TABLE "mount_targets" ("target_id" INTEGER NOT NULL REFERENCES profiles (id) ON DELETE CASCADE, "groups" TEXT NOT NULL, "version" INTEGER NOT NULL, "pending" TEXT NULL, PRIMARY KEY ("target_id"));
CREATE TABLE "profile_mounts" ("target_id" INTEGER NOT NULL REFERENCES profiles (id) ON DELETE CASCADE, "source_id" INTEGER NOT NULL REFERENCES profiles (id) ON DELETE CASCADE, "position" INTEGER NOT NULL, PRIMARY KEY ("target_id", "source_id"));
CREATE TABLE "profiles" ("id" INTEGER NOT NULL, "type" TEXT NOT NULL, "label" TEXT NOT NULL, "current_group_name" TEXT NULL, "url" TEXT NOT NULL, "age_secret_key" TEXT NULL, "last_update_date" INTEGER NULL, "extend_type" TEXT NOT NULL, "script_id" INTEGER NULL, "match_target" TEXT NULL, "auto_update_duration_millis" INTEGER NOT NULL, "subscription_info" TEXT NULL, "auto_update" INTEGER NOT NULL CHECK ("auto_update" IN (0, 1)), "selected_map" TEXT NOT NULL, "unfold_set" TEXT NOT NULL, "order" INTEGER NULL, "overrides" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "proxy_dialers" ("profile_id" INTEGER NOT NULL REFERENCES profiles (id) ON DELETE CASCADE, "proxy_id" INTEGER NOT NULL REFERENCES custom_proxies (id) ON DELETE CASCADE, "target" TEXT NOT NULL, PRIMARY KEY ("profile_id", "proxy_id"));
CREATE TABLE "proxy_groups" ("id" INTEGER NOT NULL, "profile_id" INTEGER NOT NULL REFERENCES profiles (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "proxies" TEXT NULL, "use" TEXT NULL, "definition" TEXT NOT NULL DEFAULT '{}', "order" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "rules" ("id" INTEGER NOT NULL, "profile_id" INTEGER NULL REFERENCES profiles (id) ON DELETE CASCADE, "rule_action" TEXT NOT NULL, "content" TEXT NULL, "rule_target" TEXT NULL, "rule_provider" TEXT NULL, "sub_rule" TEXT NULL, "no_resolve" INTEGER NOT NULL DEFAULT 0 CHECK ("no_resolve" IN (0, 1)), "src" INTEGER NOT NULL DEFAULT 0 CHECK ("src" IN (0, 1)), "order" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "scripts" ("id" INTEGER NOT NULL, "label" TEXT NOT NULL, "last_update_time" INTEGER NOT NULL, "url" TEXT NULL, "order" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_mitm_rewrites_profile_order ON mitm_rewrites (profile_id, "order");
CREATE INDEX idx_proxy_groups_profile_order ON proxy_groups (profile_id, "order");
CREATE INDEX idx_rule_target ON rules (rule_target);
CREATE INDEX idx_rules_profile_order ON rules (profile_id, "order");
CREATE INDEX last_accessed_url ON icon_records (last_accessed, url);
PRAGMA user_version = 31;
